INSERT INTO company_dossiers (ticker,status,description,lede,sells,revenue_model,opportunity,must_go_right,editor_note,bull_title,bull_json,bear_title,bear_json,thesis_breaker,financial_drivers_json,risks_json,monitor_json,questions_json,competitors,evidence_date,validated_at,published_at,updated_at) VALUES
('ATMU','published','Filtration-technology company supplying engine and industrial filtration products to equipment makers and aftermarket customers.','Atmus sells Fleetguard and related filtration systems that protect engines and equipment across on-highway, off-highway and industrial applications. Installed-base use, replacement demand, OEM production, distribution, price-cost and capital allocation drive value.','Fuel, lubricant, air and crankcase-ventilation filtration systems, filter media, coolants, chemicals and industrial air-filtration products.','Product sales to original-equipment manufacturers and through global aftermarket distribution, with recurring replacement demand from equipment already in service.','A large installed base, stricter emissions and uptime requirements, and expansion into adjacent industrial filtration can support durable aftermarket demand.','Atmus must preserve product performance and brand trust, serve OEM specifications, manage channel inventory, integrate acquisitions and convert price and volume into free cash flow.','Separate OEM-cycle growth from aftermarket consumption. Track installed-base exposure, channel sell-through, price-cost, customer concentration, acquisition economics, working capital, debt and free cash flow.','Replacement filtration can create recurring installed-base economics','["Filters are consumable components tied to equipment use and maintenance intervals.","A broad distribution network can support availability and customer retention.","Technical media expertise can extend into adjacent filtration markets."]','OEM cycles, concentration and acquisition leverage can weaken resilience','["Truck and equipment production can change sharply with customer demand.","Large OEM and distributor relationships can influence pricing and volume.","Acquisitions and debt may absorb cash before expected synergies appear."]','The thesis breaks if aftermarket demand and margin fail to offset OEM cyclicality while acquisitions or leverage reduce free cash flow per share','[{"label":"AFTERMARKET MIX","value":"Revenue quality","detail":"Replacement volume, channel sell-through, installed base and customer retention"},{"label":"PRICE / COST","value":"Operating proof","detail":"Pricing, materials, freight, labor, utilization and gross margin"},{"label":"CASH / CAPITAL","value":"Owner outcome","detail":"Working capital, capex, acquisitions, debt, dividends and repurchases"}]','[{"title":"OEM and industrial cycle","level":"High","text":"Equipment production and utilization affect original and replacement demand.","signal":"OEM schedules, channel inventory and aftermarket volume"},{"title":"Customer and supply concentration","level":"High","text":"Large customers and specialized inputs can affect terms and continuity.","signal":"Top-customer mix, shortages and price recovery"},{"title":"Acquisition and leverage","level":"Medium","text":"Expansion can add integration cost and fixed financial claims.","signal":"Synergies, debt, interest and free cash flow"}]','[{"title":"Installed-base demand","text":"Track replacement sell-through independently from OEM shipments and distributor stocking.","impact":"BULL CASE"},{"title":"Cash after expansion","text":"Reconcile operating cash with acquisitions, separation costs, capex and debt service.","impact":"NEUTRAL"}]','["How much revenue is recurring replacement demand rather than OEM production?","Are price and productivity offsetting material and labor inflation?","Do acquisitions increase free cash flow per diluted share after integration costs?"]','Donaldson, Mann+Hummel, Parker Hannifin and other engine or industrial filtration suppliers.','2026-02-13','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATNI','published','Communications-infrastructure operator serving rural and remote markets in the United States and Caribbean region.','ATN International builds and operates fiber, fixed broadband and mobile networks where geography and market size limit alternatives. Subscribers, service quality, public funding, network investment, storm exposure, leverage and free cash flow drive value.','Residential and business broadband, mobile voice and data, carrier services, managed connectivity and communications infrastructure.','Recurring subscriber and enterprise service fees, wholesale or roaming revenue, and selected government-supported construction or operating economics.','Underserved markets can support demand for reliable high-speed connectivity and public programs can help fund difficult network builds.','ATN must build networks at disciplined returns, retain subscribers, manage local operations, meet funding obligations and withstand weather, regulatory and competitive shocks.','Adjusted EBITDA does not fund owners by itself. Track subscribers, ARPU, churn, passings, penetration, subsidy receipts, capex, maintenance, debt, interest and free cash flow.','Local infrastructure can form durable connectivity franchises','["Broadband and mobile access are essential household and business services.","Remote-market operating experience can be difficult to replicate.","Public funding can improve project economics when milestones are met."]','Capital intensity and small-market shocks can overwhelm recurring revenue','["Network builds may require years of spending before penetration matures.","Hurricanes and remote logistics can damage assets and raise costs.","Subsidy, roaming or regulatory changes can alter expected returns."]','The thesis breaks if network investment fails to produce sustainable subscriber economics and consolidated free cash flow after debt service','[{"label":"SUBSCRIBER ECONOMICS","value":"Demand proof","detail":"Passings, penetration, subscribers, ARPU, churn and service mix"},{"label":"NETWORK RETURNS","value":"Operating proof","detail":"Build cost, subsidy, utilization, maintenance and segment margin"},{"label":"LEVERAGE / CASH","value":"Owner outcome","detail":"Capex, interest, debt maturities, dividends and free cash flow"}]','[{"title":"Build and demand execution","level":"High","text":"Penetration may not justify the cost of remote network construction.","signal":"Cost per passing, take rate, churn and ARPU"},{"title":"Weather and geography","level":"High","text":"Severe storms and remote operations can interrupt service and damage assets.","signal":"Outages, restoration cost and insurance recovery"},{"title":"Funding and regulation","level":"High","text":"Government support and communications rules can change project economics.","signal":"Awards, compliance milestones and subsidy policy"}]','[{"title":"Cohort network returns","text":"Measure penetration and cash contribution by build year and geography.","impact":"BULL CASE"},{"title":"Cash after capex","text":"Require recurring services to cover maintenance, growth capex, interest and dividends.","impact":"NEUTRAL"}]','["Which markets earn acceptable returns without continuing subsidies?","How quickly do new fiber passings convert into retained subscribers?","When does consolidated free cash flow cover leverage and shareholder distributions?"]','Regional cable, fiber and wireless operators, national carriers, satellite broadband and fixed-wireless providers.','2026-03-16','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATOM','published','Semiconductor intellectual-property company seeking to license a proprietary materials technology into chip manufacturing.','Atomera develops Mears Silicon Technology, an engineered thin-film approach intended to improve transistor performance and power efficiency using existing manufacturing equipment. Customer qualification, manufacturability, licensing terms, cash runway and dilution determine value.','Materials-engineering intellectual property, process know-how, development services and potential licenses for semiconductor fabrication.','Limited development revenue before adoption, with potential engineering fees, license payments and royalties if customers qualify and use the technology in production.','If MST produces repeatable benefits without disruptive factory changes, foundries and chipmakers could apply it across valuable analog, power, radio-frequency or advanced-node products.','Atomera must prove benefits on customer wafers, transfer a repeatable process, protect intellectual property, pass long qualification cycles and sign economic production licenses.','A development agreement is not production adoption. Track named or countable customer stages, wafer results, yield, integration steps, license scope, royalty basis, cash burn, runway and diluted shares.','Successful process adoption could create capital-light royalty economics','["Licensing can scale without owning semiconductor fabs.","Compatibility with installed equipment can lower adoption friction.","Materials improvements may address performance and power limits across several device types."]','Qualification cycles and binary customer decisions create extreme risk','["Customers may achieve similar gains through internal process changes.","Promising test wafers may fail yield, reliability or volume transfer.","Minimal revenue and long sales cycles can require repeated equity financing."]','The thesis breaks if customer evaluations do not progress to repeatable production licenses before financing meaningfully dilutes existing owners','[{"label":"CUSTOMER PROGRESSION","value":"Commercial proof","detail":"Evaluation, integration, qualification, production and license milestones"},{"label":"TECHNICAL TRANSFER","value":"Manufacturing proof","detail":"Performance, power, yield, reliability, repeatability and process cost"},{"label":"RUNWAY / RIGHTS","value":"Owner outcome","detail":"Cash burn, contract economics, royalty base, patents and diluted shares"}]','[{"title":"Technology validation","level":"High","text":"Laboratory benefits may not survive customer-specific high-volume manufacturing.","signal":"Independent wafer data, yield, reliability and repeat orders"},{"title":"Customer adoption","level":"High","text":"Large semiconductor firms have long cycles and strong internal alternatives.","signal":"Stage progression, paid work and signed licenses"},{"title":"Financing and dilution","level":"High","text":"Low revenue can force capital raises before commercial proof.","signal":"Runway, burn, offerings and share count"}]','[{"title":"Stage-gated adoption","text":"Require documented movement from evaluation to qualification and production rights.","impact":"BULL CASE"},{"title":"Per-share runway","text":"Compare time to customer decisions with cash needs and likely dilution.","impact":"BEAR CASE"}]','["What customer data proves MST improves a production-relevant device without harming yield?","Which contractual milestone converts development work into a royalty-bearing license?","How many decision cycles can current cash fund on a fully diluted basis?"]','Internal foundry research, alternative deposition or materials techniques, and other semiconductor process-IP providers.','2026-02-24','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATR','published','Global manufacturer of dispensing, sealing and drug-delivery systems for pharmaceutical and consumer products.','Aptar supplies pumps, valves, closures, elastomer components and delivery devices used in medicines, beauty, food and household products. Pharma mix, innovation, customer launches, resin and labor costs, capital intensity and acquisitions drive value.','Nasal, inhalation and injectable drug-delivery components, dispensing pumps and valves, closures, elastomer solutions and related services.','High-volume component and system sales, tooling and development revenue, and selected service economics under customer programs.','Growth in self-administered medicines, biologics and differentiated consumer packaging can increase demand for engineered delivery systems with regulatory and quality barriers.','Aptar must win customer specifications, meet strict quality requirements, scale new devices, recover input costs and earn returns on plants, tooling and acquisitions.','Track reported and organic growth by segment. Follow Pharma mix, project launches, tooling, price-cost, resin, utilization, quality events, capex, acquisition spending and free cash flow.','Drug-delivery expertise can support durable, higher-value programs','["Regulated delivery components can have long qualification and product lives.","A broad technology portfolio supports cross-selling across global customers.","Pharma growth can improve mix and resilience relative to discretionary packaging."]','Complex launches and consumer exposure can pressure returns','["Customer product delays can strand tooling and capacity.","Beauty and closure volumes remain exposed to consumer demand and price competition.","Quality failures in pharmaceutical components can create recalls and liability."]','The thesis breaks if growth projects and acquisitions fail to lift cycle-normalized return on invested capital and free cash flow per share','[{"label":"PHARMA MIX","value":"Revenue quality","detail":"Drug-delivery sales, launches, customer programs and segment margin"},{"label":"PRICE / PRODUCTIVITY","value":"Operating proof","detail":"Price-cost, resin, labor, utilization, scrap and quality"},{"label":"INVESTED CAPITAL","value":"Owner outcome","detail":"Capex, tooling, acquisitions, working capital and free cash flow"}]','[{"title":"Quality and regulation","level":"High","text":"Components used in medicines require exacting controls and documentation.","signal":"Recalls, warning letters, customer claims and remediation"},{"title":"Launch execution","level":"High","text":"Device programs can require capital before customer demand is established.","signal":"Qualification, launch timing, utilization and write-offs"},{"title":"Consumer and input cycle","level":"Medium","text":"Beauty and closure demand and raw-material spreads can fluctuate.","signal":"Organic volume, resin, pricing and channel inventory"}]','[{"title":"Program lifetime value","text":"Track qualified launches through volume ramp, margin and retained customer use.","impact":"BULL CASE"},{"title":"Return on growth capital","text":"Compare incremental operating profit with capex, tooling and acquisitions.","impact":"NEUTRAL"}]','["Which pharma launches provide contracted or highly visible multi-year volume?","Are productivity and pricing keeping pace with labor and material costs?","Does free cash flow support expansion and acquisitions without weakening per-share returns?"]','West Pharmaceutical Services, Berry Global, Silgan, Gerresheimer and other drug-delivery or dispensing suppliers.','2026-02-06','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATRC','published','Medical-device company developing surgical treatments for atrial fibrillation, left-atrial-appendage management and post-operative pain.','AtriCure sells ablation systems, AtriClip devices and cryo-nerve products used by cardiac and thoracic surgeons. Procedure adoption, clinical evidence, reimbursement, training, product safety, gross margin and operating leverage drive value.','Surgical ablation devices, left-atrial-appendage exclusion systems, hybrid atrial-fibrillation therapy tools and cryoablation probes for pain management.','Single-use device sales tied to procedures, plus equipment, accessories and international distribution economics.','Large undertreated atrial-fibrillation populations and broader use of appendage management or post-operative pain therapies can expand addressable procedures.','AtriCure must demonstrate durable clinical outcomes, train surgeons, secure guideline and reimbursement support, maintain regulatory compliance and scale without sacrificing product quality.','Procedure growth matters more than shipments to distributors. Track active accounts, trained surgeons, procedures per account, therapy mix, reimbursement, clinical endpoints, gross margin, sales expense and free cash flow.','Clinical adoption can build recurring procedure-driven growth','["Single-use products create repeat revenue as procedure volume grows.","A broad surgical portfolio can deepen hospital and surgeon relationships.","Clinical evidence and training can expand treatment of undertreated patients."]','Adoption, competition and clinical risk remain material','["Surgical workflows change slowly and depend on trained physicians.","Adverse outcomes, recalls or weaker evidence can limit guideline support.","Rapid sales-force expansion may outpace procedure productivity and cash generation."]','The thesis breaks if procedure adoption stalls or clinical and reimbursement evidence fails to support profitable expansion','[{"label":"PROCEDURE VOLUME","value":"Demand proof","detail":"Active surgeons, accounts, cases per account, therapy mix and geography"},{"label":"CLINICAL / ACCESS","value":"Adoption proof","detail":"Outcomes, guidelines, reimbursement, training and safety"},{"label":"OPERATING LEVERAGE","value":"Owner outcome","detail":"Gross margin, sales productivity, R&D, free cash flow and diluted shares"}]','[{"title":"Clinical and product safety","level":"High","text":"Poor outcomes or device problems can harm patients and adoption.","signal":"Trial results, adverse events, recalls and claims"},{"title":"Physician and hospital adoption","level":"High","text":"Training, budgets and competing procedures influence utilization.","signal":"Repeat surgeons, cases per account and pricing"},{"title":"Regulatory and reimbursement","level":"High","text":"Label, guideline or payment changes can limit procedure growth.","signal":"FDA actions, coverage policy and coding"}]','[{"title":"Repeat procedure cohorts","text":"Measure utilization by trained-surgeon and hospital cohort, not account count alone.","impact":"BULL CASE"},{"title":"Sales-force productivity","text":"Require incremental gross profit to exceed training and commercial expansion costs.","impact":"NEUTRAL"}]','["Which indications and products drive repeat procedures rather than initial trials?","What clinical evidence changes guidelines or referral patterns?","When does procedure growth produce durable positive free cash flow?"]','Boston Scientific, Medtronic, Johnson & Johnson, Abbott and surgical-device alternatives.','2026-02-19','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('ATRO','published','Aerospace and defense supplier providing aircraft power, connectivity, lighting, structures and test systems.','Astronics sells specialized components and systems into commercial aviation, defense and other mission-critical markets. Aircraft production, retrofit demand, backlog conversion, customer concentration, certification, supply execution and cash generation drive value.','Aircraft electrical power and connectivity systems, lighting and interiors, structures, avionics, test equipment and simulation technologies.','Product and engineering sales under production, retrofit and development programs, plus aftermarket and service activity.','Higher aircraft production, cabin electrification, connectivity upgrades, defense programs and fleet retrofits can expand content and aftermarket demand.','Astronics must convert backlog on schedule, qualify new content, manage suppliers, meet aerospace quality standards and fund working capital without eroding margins.','Backlog is conditional on customer schedules. Track book-to-bill, shipset content, production rates, aftermarket mix, program margin, supplier shortages, inventory, receivables, debt and free cash flow.','Qualified aircraft content can generate long program lives','["Certification and integration create switching costs after program selection.","Commercial recovery and retrofit demand can lift volume and mix.","Power and connectivity needs can increase content per aircraft."]','Customer schedules and execution can make backlog deceptive','["Airframe or airline delays can move deliveries and cash collection.","Specialized suppliers and quality requirements can constrain output.","Fixed-price development and test programs can produce cost overruns."]','The thesis breaks if backlog growth does not convert into sustainable margin, working-capital release and free cash flow','[{"label":"BACKLOG CONVERSION","value":"Demand proof","detail":"Orders, cancellations, production schedules, deliveries and book-to-bill"},{"label":"PROGRAM ECONOMICS","value":"Operating proof","detail":"Content, mix, pricing, engineering cost, quality and segment margin"},{"label":"CASH CONVERSION","value":"Owner outcome","detail":"Inventory, receivables, capex, debt and free cash flow"}]','[{"title":"Customer and program concentration","level":"High","text":"Large airframers and programs can alter production schedules.","signal":"Customer releases, backlog revisions and build rates"},{"title":"Supply and quality","level":"High","text":"Shortages or defects can delay certified aerospace deliveries.","signal":"Past-due backlog, expedite cost, scrap and returns"},{"title":"Contract execution","level":"High","text":"Development and test programs may exceed original cost estimates.","signal":"Charges, milestones and estimate-at-completion changes"}]','[{"title":"Backlog aging","text":"Map orders to customer production slots, delivery timing and expected margin.","impact":"BULL CASE"},{"title":"Working-capital release","text":"Require higher shipments to reduce inventory and convert earnings into cash.","impact":"NEUTRAL"}]','["How much backlog is supported by firm near-term customer schedules?","Which new platforms increase content and recurring aftermarket opportunity?","When do inventory and receivables normalize into free cash flow?"]','Collins Aerospace, Honeywell, Safran, Crane and specialized aerospace electronics or test suppliers.','2026-02-26','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('AU','published','Global gold producer operating mines and development projects across multiple jurisdictions.','AngloGold Ashanti converts mineral reserves into gold through capital-intensive, technically complex mines. Gold price, production, grade, recovery, all-in sustaining cost, reserve replacement, project execution, safety and jurisdiction determine owner value.','Gold and by-products produced from open-pit and underground mines, plus exploration and development projects.','Commodity sales at market-linked prices, with cash economics determined by ounces sold, realized price, royalties, operating cost, sustaining capital and taxes.','Higher gold prices, operational improvement, reserve additions and disciplined project development can expand mine cash flow and portfolio life.','The company must operate safely, deliver planned tonnes and grades, control costs, replace depleted reserves and allocate capital across politically diverse assets.','Reported earnings can follow gold prices while mine quality deteriorates. Track ounces, grade, recovery, all-in sustaining cost, sustaining and growth capex, reserves, jurisdictional payments, closure obligations and free cash flow per share.','A diversified reserve base can provide leveraged gold exposure','["Multiple mines reduce dependence on a single orebody.","Long-lived reserves and exploration can extend production optionality.","Higher realized gold prices can expand cash flow rapidly when unit costs are controlled."]','Mining risk can consume favorable commodity prices','["Grade, recovery, geotechnical or equipment problems can reduce production.","Inflation, royalties and capital needs can raise all-in cost.","Political, permitting, safety and environmental events can impair asset value."]','The thesis breaks if reserve depletion and rising all-in costs prevent sustained per-share free cash flow across conservative gold-price assumptions','[{"label":"PRODUCTION QUALITY","value":"Operating proof","detail":"Ounces, tonnes, grade, recovery, downtime and guidance reconciliation"},{"label":"ALL-IN COST","value":"Economic proof","detail":"Cash cost, sustaining capex, royalties, taxes and inflation"},{"label":"RESERVES / CAPITAL","value":"Owner outcome","detail":"Reserve replacement, project returns, closure liabilities, debt and shares"}]','[{"title":"Mine execution and safety","level":"High","text":"Technical failures or accidents can stop production and harm people.","signal":"Fatalities, stoppages, grade and recovery misses"},{"title":"Jurisdiction and permitting","level":"High","text":"Taxes, royalties, licenses and community agreements can change economics.","signal":"Law changes, disputes, permits and social license"},{"title":"Commodity and capital allocation","level":"High","text":"High gold prices can encourage marginal projects and expensive acquisitions.","signal":"Reserve price, project hurdle, deal price and free cash flow"}]','[{"title":"Mine-by-mine reconciliation","text":"Compare actual grade, recovery, cost and capital with technical plans.","impact":"NEUTRAL"},{"title":"Per-share reserve value","text":"Track economically mineable reserves after depletion, cost inflation and dilution.","impact":"BULL CASE"}]','["Which mines generate free cash flow at a conservative gold price?","Are reserve additions economic after development and closure capital?","How much jurisdictional and project risk is concentrated in the growth plan?"]','Newmont, Barrick Mining, Gold Fields, Agnico Eagle and other global gold producers.','2026-03-26','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('AUB','published','Regional bank holding company serving commercial and consumer customers across Virginia and nearby markets.','Atlantic Union Bankshares earns spread and fee income from loans, deposits, treasury, wealth and related services. Deposit quality, net interest margin, credit, merger integration, capital and tangible book value drive owner returns.','Commercial and consumer loans, deposits, treasury management, mortgage, wealth, equipment finance and capital-markets services.','Net interest income from loans and securities funded by deposits, plus wealth, service, interchange, mortgage and other fee income.','A broader regional franchise can deepen commercial relationships and improve scale if acquired customers, deposits and bankers are retained.','The bank must integrate acquisitions, retain low-cost deposits, price credit correctly, manage commercial real-estate exposure and maintain capital through rate and loss cycles.','Acquisition size is not value by itself. Track core deposits, deposit beta, net interest margin, loan yields, nonperformers, criticized assets, charge-offs, merger costs, tangible-book dilution and capital ratios.','Scale and relationship deposits can improve regional-bank economics','["A dense regional footprint can support commercial cross-selling.","Core operating deposits can provide durable funding value.","Successful integration can spread technology and compliance costs across a larger base."]','Credit and integration risk can erase apparent deal benefits','["Deposit attrition or repricing can reduce expected funding synergies.","Commercial real-estate and regional concentrations can amplify losses.","Merger charges and tangible-book dilution can delay per-share value creation."]','The thesis breaks if integration and credit costs prevent recovery of tangible book value and normalized earnings per share','[{"label":"DEPOSIT FRANCHISE","value":"Funding quality","detail":"Core mix, uninsured deposits, cost, beta, retention and customer concentration"},{"label":"CREDIT / MARGIN","value":"Earning quality","detail":"Loan mix, margin, criticized assets, nonperformers, losses and reserves"},{"label":"MERGER / CAPITAL","value":"Owner outcome","detail":"Synergies, costs, tangible-book dilution, capital ratios, dividends and shares"}]','[{"title":"Integration and deposit retention","level":"High","text":"Systems and relationship disruption can lose customers and expected synergies.","signal":"Deposit outflow, banker turnover, conversion issues and costs"},{"title":"Commercial credit","level":"High","text":"Regional commercial and real-estate losses can rise together.","signal":"Criticized loans, delinquencies, collateral and charge-offs"},{"title":"Rate and liquidity","level":"High","text":"Deposit pricing and securities duration can pressure margin and capital.","signal":"Deposit beta, wholesale funding, margin and unrealized loss"}]','[{"title":"Merger scorecard","text":"Track customer retention, cost saves, credit marks and tangible-book earn-back each quarter.","impact":"NEUTRAL"},{"title":"Deposit cohorts","text":"Separate acquired and legacy deposit retention, mix and pricing.","impact":"BULL CASE"}]','["Are acquired customers and relationship deposits being retained after conversion?","What losses are embedded in acquired and legacy credit portfolios?","When does tangible book value per share recover after merger dilution?"]','Truist, M&T Bank, regional banks, community banks and credit unions in the Mid-Atlantic.','2026-02-26','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('AUGO','published','Multi-mine gold and copper producer operating assets and development projects in the Americas.','Aura Minerals operates mines in Brazil, Mexico and Honduras and develops additional projects. Metal prices, ounces, grades, recoveries, all-in sustaining cost, mine life, project execution, jurisdiction and capital returns drive value.','Gold and copper concentrates or doré from operating mines, supported by exploration and mine-development projects.','Commodity sales at market-linked prices, less treatment, transport, royalties, operating cost, sustaining capital and taxes.','Exploration, mine optimization and new projects can add production and reserves if built at attractive full-cycle returns.','Aura must deliver mine plans, replace reserves, commission projects safely, control cost and navigate permitting, royalties and community relationships across jurisdictions.','Production growth is not enough. Track each mine by grade, recovery, payable metal, all-in sustaining cost, sustaining and growth capex, reserves, mine life, taxes, dividends, debt and diluted shares.','Multiple mines and projects can compound reserve and production growth','["A portfolio reduces dependence on one mine or orebody.","Exploration near existing infrastructure can be capital efficient.","Strong metal prices can fund development and shareholder returns."]','Small-portfolio mining and project risk remain concentrated','["A disruption at one mine can materially affect consolidated output.","New projects can miss cost, schedule, grade or recovery assumptions.","Jurisdictional, environmental and community events can delay cash flow."]','The thesis breaks if growth capex and depletion fail to create increasing mine-level and per-share free cash flow at conservative metal prices','[{"label":"MINE OPERATIONS","value":"Production proof","detail":"Tonnes, grade, recovery, payable metal, downtime and guidance"},{"label":"ALL-IN COST","value":"Economic proof","detail":"Operating cost, royalties, sustaining capex, inflation and taxes"},{"label":"PROJECT / RESERVES","value":"Owner outcome","detail":"Build cost, schedule, reserves, mine life, debt, dividends and shares"}]','[{"title":"Single-mine disruption","level":"High","text":"A limited mine portfolio makes operational misses material.","signal":"Downtime, grade control, recovery and guidance changes"},{"title":"Project execution","level":"High","text":"Construction and ramp-up may exceed cost or schedule assumptions.","signal":"Capital revisions, commissioning and nameplate recovery"},{"title":"Jurisdiction and social license","level":"High","text":"Permits, taxes, communities and environmental obligations affect continuity.","signal":"License status, disputes, payments and remediation"}]','[{"title":"Mine-by-mine cash bridge","text":"Reconcile payable metal and price with cost, royalties, tax and sustaining capital.","impact":"NEUTRAL"},{"title":"Growth-capital return","text":"Compare project cash flow with original cost, schedule and reserve assumptions.","impact":"BULL CASE"}]','["Which mines remain cash generative under conservative gold and copper prices?","Are new projects meeting original capital and ramp assumptions?","Does reserve replacement exceed depletion after full exploration and development cost?"]','Alamos Gold, Eldorado Gold, Equinox Gold, Lundin Gold and other Americas-focused precious-metals producers.','2026-04-01','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP),
('AUPH','published','Commercial-stage biopharmaceutical company focused on autoimmune disease and lupus nephritis.','Aurinia markets LUPKYNIS, an oral voclosporin therapy for adults with active lupus nephritis, and develops additional autoimmune programs. Patient starts, persistence, access, net price, safety, competition, pipeline evidence and capital allocation drive value.','LUPKYNIS prescription therapy and investigational autoimmune biologic programs including aritinercept.','U.S. product sales net of rebates and discounts, plus licensing, supply, milestone or royalty economics in partnered territories.','Earlier treatment, improved diagnosis and broader physician adoption can expand lupus-nephritis therapy, while a successful pipeline could reduce single-product concentration.','Aurinia must retain treated patients, improve access, compete on clinical value, maintain supply and safety, protect exclusivity and fund pipeline programs with disciplined evidence gates.','Prescriptions are not durable patients. Track new starts, patients on therapy, persistence, prescribers, covered lives, gross-to-net, inventory, discontinuations, safety, operating cash and pipeline milestones.','A differentiated approved therapy can build a durable autoimmune franchise','["Lupus nephritis has serious consequences and requires effective disease control.","Commercial infrastructure can support deeper specialist adoption.","A successful follow-on program could diversify product concentration."]','Single-product and competitive risk remain decisive','["Adoption may be limited by payer controls, safety monitoring or competing regimens.","Patient discontinuation can weaken the value of new starts.","Pipeline spending may not produce clinical diversification before exclusivity declines."]','The thesis breaks if sustained LUPKYNIS patient use and cash generation fail to support the franchise and evidence-based pipeline investment','[{"label":"PATIENT COHORTS","value":"Commercial proof","detail":"Starts, persistence, discontinuation, prescribers and geography"},{"label":"ACCESS / NET PRICE","value":"Revenue quality","detail":"Coverage, prior authorization, rebates, discounts and net revenue per patient"},{"label":"FRANCHISE / CASH","value":"Owner outcome","detail":"Competition, safety, exclusivity, pipeline milestones, operating cash and shares"}]','[{"title":"Commercial concentration","level":"High","text":"Most value depends on one therapy and one principal indication.","signal":"Patient persistence, market share and net sales"},{"title":"Access, safety and competition","level":"High","text":"Payers, prescribers and competing treatments influence sustained use.","signal":"Coverage, discontinuation, adverse events and guidelines"},{"title":"Pipeline and capital allocation","level":"Medium","text":"Development programs can consume commercial cash without adequate evidence.","signal":"Trial design, milestones, R&D and share count"}]','[{"title":"Persistence cohorts","text":"Track patients remaining on therapy by start quarter rather than cumulative starts.","impact":"BULL CASE"},{"title":"Cash-supported pipeline","text":"Require clinical milestones that justify each increase in development spending.","impact":"NEUTRAL"}]','["What proportion of new patients remain on LUPKYNIS after six and twelve months?","How do coverage and gross-to-net differ across major payer channels?","What evidence would justify advancing aritinercept into expensive pivotal development?"]','GSK and other lupus-nephritis therapies, immunosuppressive regimens and autoimmune-drug developers.','2026-02-26','2026-08-05T13:10:00Z',CURRENT_TIMESTAMP,CURRENT_TIMESTAMP)
